import urllib.request, json, os

url = 'http://127.0.0.1:8766/mcp'
base_headers = {
    'Content-Type': 'application/json',
    'Accept': 'application/json, text/event-stream',
    'Authorization': 'Bearer ' + os.environ['AGPOLICY_TOKEN']
}

def post(payload, sid=None):
    h = dict(base_headers)
    if sid:
        h['mcp-session-id'] = sid
    req = urllib.request.Request(url, data=json.dumps(payload).encode(), headers=h)
    with urllib.request.urlopen(req) as resp:
        return resp.headers.get('mcp-session-id'), resp.read().decode()

sid, body = post({
    'jsonrpc': '2.0', 'id': 1, 'method': 'initialize',
    'params': {'protocolVersion': '2024-11-05', 'capabilities': {}, 'clientInfo': {'name': 'client', 'version': '1.0'}}
})
post({'jsonrpc': '2.0', 'method': 'notifications/initialized'}, sid)
_, tools_body = post({'jsonrpc': '2.0', 'id': 2, 'method': 'tools/list', 'params': {}}, sid)
for line in tools_body.splitlines():
    if line.startswith('data: '):
        data = json.loads(line[6:])
        for t in data['result']['tools']:
            print('=== TOOL:', t['name'], '===')
            print(t.get('description', ''))
            print(json.dumps(t.get('inputSchema', {}), indent=2))
